        "PRODUCT_OR_PROP",
        "LOCATION",
        "BACKGROUND_ELEMENTS",
        "MAIN_TEXT",
        "SECONDARY_TEXT",
        "ACCENT_SYMBOL",
        "WARDROBE_STYLE",
        "STYLE_FIDELITY_ANCHORS",
        "SOURCE_CONTENT_TO_AVOID",
        "ASPECT_RATIO"
